import{_ as i,C as a,o as n,c as d,ao as t,E as o}from"./chunks/framework.ucUddl5u.js";const m=JSON.parse('{"title":"Your first session","description":"","frontmatter":{},"headers":[],"relativePath":"start/tour.md","filePath":"start/tour.md","lastUpdated":null}'),h={name:"start/tour.md"};function l(c,e,p,u,g,w){const r=a("DemoShot"),s=a("DemoLoop");return n(),d("div",null,[e[0]||(e[0]=t('<h1 id="Your-first-session" tabindex="-1">Your first session <a class="header-anchor" href="#Your-first-session" aria-label="Permalink to &quot;Your first session {#Your-first-session}&quot;">​</a></h1><p>A first-session walkthrough: the window, the agent, the modes and the drawers, and the keys you use most. The keys below are the built-in defaults; see <a href="./../ref/keybindings">Keybindings</a> for how to rebind them.</p><p>If Ship of Tools is not installed yet, start with the <a href="./quickstart">Quickstart</a>.</p><h2 id="The-window" tabindex="-1">The window <a class="header-anchor" href="#The-window" aria-label="Permalink to &quot;The window {#The-window}&quot;">​</a></h2><p>The window has three columns. When the bottom drawer is open it sits under the navigation and preview columns; the agent column always runs the full height of the window.</p>',5)),o(r,{path:"layout-labelled.png",caption:"The default layout with the Julia drawer open: navigation, preview and drawer on the left, the agent column full height on the right."}),e[1]||(e[1]=t('<p>The left column is the <strong>navigation</strong> tree, a collapsible outline whose root you switch with one key. The middle column is the <strong>preview</strong> of whatever you have selected. The right column is the <strong>agent pane</strong>; its title bar reads <code>llm</code>. The focused pane&#39;s title bar instead shows the pane&#39;s name and its main keys, so with focus the agent pane&#39;s title reads <code>Agent</code> followed by its keys. The drawer shows the Julia REPL, a terminal, the host monitor or Help. Below the drawer, the row of names along the bottom edge is the session strip, one entry per session; the window&#39;s own bottom border reads <code>fe &lt;version&gt; · be &lt;version&gt;</code>, highlighted when they differ. See <a href="./../guide/interface">The interface</a>.</p><p>Three plain lines sit around the navigation tree: <code>status:</code> above it shows the connection, the active workspace and a revision count; <code>annotation:</code> below it says whether the entry under the cursor has a <a href="./../guide/concept-layer">concept annotation</a>; <code>key:</code> at the bottom is the last key the window received.</p><p>On first launch the window opens in Files mode and the agent pane is empty: nothing runs there until you create a session.</p><h2 id="The-agent" tabindex="-1">The agent <a class="header-anchor" href="#The-agent" aria-label="Permalink to &quot;The agent {#The-agent}&quot;">​</a></h2><ol><li><p><strong>Create a session.</strong> Press <code>s</code> for Sessions mode and pick <code>[+ create new]</code>; the keys are in <a href="/ship-of-tools/dev/start/quickstart#start-session">Start an agent session</a>.</p></li><li><p><strong>Type a request.</strong> Move focus to the agent pane (<code>Ctrl+Right</code>, twice from the navigation pane) and type into it as you would into Claude Code or Codex in a terminal; it is the same program.</p></li><li><p><strong>It runs code in your REPL.</strong> A Claude Code session runs Julia in the session&#39;s persistent REPL, the one <code>Ctrl+J</code> opens, and each of its runs appears in that drawer. See <a href="/ship-of-tools/dev/guide/repl#agents-repl">How agents use the REPL</a>.</p></li><li><p><strong>It shows you figures.</strong> A figure the agent produces is saved to a file, and the agent can put it in your preview pane with <code>show-result</code>; figures you produce yourself at the REPL prompt appear inline in the drawer.</p></li><li><p><strong>Watch the row colour.</strong> In Sessions mode the row colour shows whether the agent is working, waiting for your answer or done; the colours are in <a href="./../concepts/work-state">Work-state colours</a>.</p></li></ol><p>The session keeps running when you switch rows or close the window.</p><h2 id="Files-mode-—-f" tabindex="-1">Files mode — <code>f</code> <a class="header-anchor" href="#Files-mode-—-f" aria-label="Permalink to &quot;Files mode — `f` {#Files-mode-—-f}&quot;">​</a></h2><p>Press <code>f</code> for <strong>Files mode</strong>: filesystem navigation over the project. Move with the arrow keys — <code>↑</code> / <code>↓</code> to move through the tree, <code>→</code> to descend into a directory, <code>←</code> to go back up. As you move, the <strong>preview pane</strong> renders the selected file: markdown rendered, images shown, <code>.jl</code> files syntax-highlighted, PDF pages rasterized, and a poster frame for video.</p><p>To edit a file yourself, move focus to the preview (<code>Ctrl+Right</code>) and press <code>e</code>: the file opens in the built-in editor in the preview pane. <code>Ctrl+S</code> saves; <code>Escape</code> closes it, and asks first if there are unsaved edits. When the entry has a concept annotation, <code>e</code> edits the annotation instead.</p>',9)),o(r,{name:"nav-files",caption:"Files mode with src/DemoProject.jl selected; its source in the preview."}),e[2]||(e[2]=t('<p>For what each file type renders and how, see <a href="./../guide/previews">Previews</a>.</p><h2 id="Modules-mode-—-m" tabindex="-1">Modules mode — <code>m</code> <a class="header-anchor" href="#Modules-mode-—-m" aria-label="Permalink to &quot;Modules mode — `m` {#Modules-mode-—-m}&quot;">​</a></h2><p>Press <code>m</code> for <strong>Modules mode</strong>: a structural view of the code, derived mechanically from <code>JuliaSyntax.jl</code> — modules and their definitions: types, functions, macros and submodules, with each type&#39;s constructors under it. It is read-only. Cursor position is preserved per mode, so switching <code>f</code> ↔ <code>m</code> returns you to where you were in each.</p>',3)),o(s,{name:"modules",caption:"Modules mode: the cursor moves through a module's definitions, with docstring and source in the preview."}),e[3]||(e[3]=t('<p>The full set of modes and their column shapes is in <a href="./../guide/modes">Modes</a>.</p><h2 id="The-REPL-drawer-—-CtrlJ" tabindex="-1">The REPL drawer — <code>Ctrl+J</code> <a class="header-anchor" href="#The-REPL-drawer-—-CtrlJ" aria-label="Permalink to &quot;The REPL drawer — `Ctrl+J` {#The-REPL-drawer-—-CtrlJ}&quot;">​</a></h2><p>Press <code>Ctrl+J</code> to open the <strong>REPL</strong> in the bottom drawer: a persistent Julia session that persists across drawer switches and frontend restarts. From Files mode you can run a whole <code>.jl</code> file in it without retyping — <code>r</code> runs it in a fresh REPL (this also clears what the agent built in <code>Main</code>), <code>Shift+R</code> includes it in the current one. At the prompt, type an expression and press Enter to run it (Shift+Enter inserts a newline); values, printed output, errors and images appear below it as they arrive.</p>',3)),o(r,{name:"repl-figure",caption:"The Julia drawer after running scripts/route.jl: the printed output and the figure inline."}),e[4]||(e[4]=t('<p>For file dispatch and the display protocol, see <a href="./../guide/repl">The REPL</a>.</p><h2 id="The-Terminal-drawer-—-CtrlT" tabindex="-1">The Terminal drawer — <code>Ctrl+T</code> <a class="header-anchor" href="#The-Terminal-drawer-—-CtrlT" aria-label="Permalink to &quot;The Terminal drawer — `Ctrl+T` {#The-Terminal-drawer-—-CtrlT}&quot;">​</a></h2><p>Press <code>Ctrl+T</code> for a local <strong>Terminal</strong> — an OS shell on the frontend machine, typically used to SSH out to backend hosts. The REPL and Terminal share one physical drawer slot: <code>Ctrl+J</code> and <code>Ctrl+T</code> each toggle their own pane, and pressing the other key swaps the content. See <a href="/ship-of-tools/dev/guide/interface#The-Terminal-Drawer">The interface</a>.</p><h2 id="The-Monitor-drawer-—-CtrlM" tabindex="-1">The Monitor drawer — <code>Ctrl+M</code> <a class="header-anchor" href="#The-Monitor-drawer-—-CtrlM" aria-label="Permalink to &quot;The Monitor drawer — `Ctrl+M` {#The-Monitor-drawer-—-CtrlM}&quot;">​</a></h2><p>Press <code>Ctrl+M</code> for the <strong>Monitor</strong> drawer: CPU, memory and GPU history for your Linux hosts, read from <code>/proc</code> and <code>nvidia-smi</code> with no extra privileges (the sampler is a Linux script; a macOS host has no <code>/proc</code> to read). Which hosts it shows is configured in <code>hosts.toml</code>; see <a href="/ship-of-tools/dev/guide/interface#The-Monitor-Drawer">The Monitor drawer</a>.</p><h2 id="Navigation-modes:-Sessions-—-s-—-and-Hosts-—-h" tabindex="-1">Navigation modes: Sessions — <code>s</code> — and Hosts — <code>h</code> <a class="header-anchor" href="#Navigation-modes:-Sessions-—-s-—-and-Hosts-—-h" aria-label="Permalink to &quot;Navigation modes: Sessions — `s` — and Hosts — `h` {#Navigation-modes:-Sessions-—-s-—-and-Hosts-—-h}&quot;">​</a></h2><p>Two more nav-tree roots switch the <em>target</em>, not the content:</p><ul><li><p><strong><code>s</code> — Sessions.</strong> Every session on every connected host, and <code>[+ create new]</code> to start one (see <a href="/ship-of-tools/dev/start/tour#The-agent">The agent</a> above). What a session is, and what it shares with other sessions, is in <a href="./../concepts/sessions">Sessions and persistence</a>.</p></li><li><p><strong><code>h</code> — Hosts.</strong> List the connected backend hosts; <code>Enter</code> jumps to that host&#39;s sessions. See <a href="/ship-of-tools/dev/guide/modes#hosts-mode">Hosts mode</a>.</p></li></ul><h2 id="Help-—-Ctrl?-and-F1" tabindex="-1">Help — <code>Ctrl+?</code> and <code>F1</code> <a class="header-anchor" href="#Help-—-Ctrl?-and-F1" aria-label="Permalink to &quot;Help — `Ctrl+?` and `F1` {#Help-—-Ctrl?-and-F1}&quot;">​</a></h2><p>Press <code>Ctrl+?</code> for a five-second overlay of the focused pane&#39;s actions with their live bindings; press it again for the searchable Help drawer, or open the drawer directly with <code>F1</code>. Help lists the bindings in effect, including your rebinds.</p>',10)),o(s,{name:"help",caption:"The Help drawer (Ctrl+? twice): Tab widens the scope to all panes, typing zoom filters the actions, Down steps through them."}),e[5]||(e[5]=t('<h2 id="Layout-and-focus" tabindex="-1">Layout and focus <a class="header-anchor" href="#Layout-and-focus" aria-label="Permalink to &quot;Layout and focus {#Layout-and-focus}&quot;">​</a></h2><p>A few global keys manage the window itself:</p><table tabindex="0"><thead><tr><th style="text-align:right;">Action</th><th style="text-align:right;">Key</th><th style="text-align:right;">What it does</th></tr></thead><tbody><tr><td style="text-align:right;">Move pane focus</td><td style="text-align:right;"><code>Ctrl+Arrow</code></td><td style="text-align:right;">shift focus spatially between the panes</td></tr><tr><td style="text-align:right;">Next / previous session</td><td style="text-align:right;"><code>Shift+Arrow</code></td><td style="text-align:right;">make the next or previous session in the strip the active one (left / right)</td></tr><tr><td style="text-align:right;">Maximize pane</td><td style="text-align:right;"><code>Alt+=</code></td><td style="text-align:right;">fill the window with the focused pane</td></tr><tr><td style="text-align:right;">Wide-preview</td><td style="text-align:right;"><code>Alt++</code></td><td style="text-align:right;">hide the agent pane and widen the preview pane</td></tr><tr><td style="text-align:right;">Restore layout</td><td style="text-align:right;"><code>Esc</code></td><td style="text-align:right;">one layer per press: un-maximize first, then exit wide-preview (only while maximized or in wide-preview)</td></tr><tr><td style="text-align:right;">Font scale</td><td style="text-align:right;"><code>Ctrl+=</code> / <code>Ctrl+-</code></td><td style="text-align:right;">zoom the UI font up / down (<code>Ctrl+0</code> resets)</td></tr><tr><td style="text-align:right;">Reconnect</td><td style="text-align:right;"><code>F5</code></td><td style="text-align:right;">reconnect the transport after a drop</td></tr><tr><td style="text-align:right;">Quit</td><td style="text-align:right;"><code>Ctrl+Q</code></td><td style="text-align:right;">real quit (nav focus only)</td></tr></tbody></table><p>Plain arrows move within a pane, <code>Ctrl+Arrow</code> moves <em>between</em> panes, and <code>Shift+Arrow</code> switches sessions. The same chords are scoped so they do not conflict: in a text editor <code>Shift+Arrow</code> extends the selection, and in an image preview <code>Shift+Up</code> and <code>Shift+Down</code> zoom.</p><h2 id="Where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#Where-to-go-next" aria-label="Permalink to &quot;Where to go next {#Where-to-go-next}&quot;">​</a></h2><ul><li><p><a href="./../guide/architecture">Architecture</a> — the three processes and why the language split.</p></li><li><p><a href="./../guide/modes">Modes</a> and <a href="./../guide/previews">Previews</a> — the nav surface in depth.</p></li><li><p><a href="./../guide/repl">The REPL</a> and <a href="./../guide/agents">Running several agents</a> — running code and driving agent sessions.</p></li><li><p><a href="./../extend/hdf5">Tutorial: an HDF5 preview</a> and <a href="./../extend/abi">The dispatch ABI</a> — add a preview for a new file type.</p></li></ul>',6))])}const y=i(h,[["render",l]]);export{m as __pageData,y as default};
